import fs from "node:fs/promises";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import { loadModel, MODEL_PATH } from "./model.mjs";

const PROJECT_DIRECTORY = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  ".."
);
const OUTPUT_PATH = path.join(PROJECT_DIRECTORY, "lib", "ml_model.rb");

export function generateRubyModel(model) {
  const rubyLabels = model.labels.map((label) => `"${label}"`).join(", ");

  return `# Generated from data/model.json model metadata.
# Do not edit this file directly; run scripts/generate-ml-model.mjs.
# Neural-network weights are compiled into the firmware by ML4F.
class MLModel
  LABELS = [${rubyLabels}]
  LABEL_CIRCLE = 0
  LABEL_POSE = 1
  LABEL_SIDE = 2
  LABEL_UP = 3
  LABEL_DOWN = 4

  def evaluate(x_values, y_values, z_values)
    Microbit::ML.evaluate(
      x_values,
      y_values,
      z_values
    )
  end
end
`;
}

async function main() {
  const model = await loadModel();
  await fs.writeFile(OUTPUT_PATH, generateRubyModel(model));
  console.log(
    `Generated ${path.relative(process.cwd(), OUTPUT_PATH)} from ` +
      path.relative(process.cwd(), MODEL_PATH)
  );
}

if (
  process.argv[1] &&
  import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href
) {
  await main();
}
